     as_of: str
     units: tuple[EvidenceUnit, ...]
     _conflicted_ids: frozenset[str] = field(default_factory=frozenset)
     _foreign_ids: frozenset[str] = field(default_factory=frozenset)
     _malformed: tuple[tuple[str, str], ...] = ()

